inline int RequiredLevel(int rank_id, int ability_id, int ordinal, int expansion) {
	const auto it = std::lower_bound(std::begin(Ranks), std::end(Ranks), rank_id,
		[](const RankPolicy& row, int id) { return row.rank_id < id; });
	return it != std::end(Ranks) && it->rank_id == rank_id && it->ability_id == ability_id &&
		it->ordinal == ordinal && it->expansion == expansion ? it->level : 0;
}
